package presets

import (
	"encoding/json"
	"fmt"
	"net/netip"
	"net/url"
	"regexp"
	"strings"
)

// The client rejects a whole catalog over one bad entry (engine/core/presets
// Parse), so a release it would reject takes every group away from every
// device it reaches. What follows mirrors the client's checks exactly:
// presets.Parse and routing.ValidateValues/NormalizeValue. A stored rule
// must already be canonical, as the client demands. testdata/rule-parity.json
// is generated by the client's own normalizer and pins the two together.

const (
	maxCatalogBytes     = 1024 * 1024
	maxServices         = 200
	maxRulesPerCategory = 2000
)

var (
	validID     = regexp.MustCompile(`^[a-z0-9][a-z0-9-]{0,63}$`)
	domainLabel = regexp.MustCompile(`^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$`)
	platforms   = []string{"windows", "darwin", "linux"}
)

func validPlatform(p string) bool {
	return p == "windows" || p == "darwin" || p == "linux"
}

// ValidID is the client's id form, for groups, icons and presets alike.
func ValidID(id string) bool { return validID.MatchString(id) }

// ValidateGroup is what saving a group checks: everything the client would
// check of it as a service.
func ValidateGroup(g Group) error {
	return validateService(Service{
		ID: g.ID, Name: g.Name, Icon: g.Icon,
		Domains: g.Rules.Domains, IPs: g.Rules.IPs,
		Processes: g.Rules.Processes, Folders: g.Rules.Folders,
	})
}

// ValidateCatalog checks a release's services as the client will parse them.
func ValidateCatalog(services []Service) error {
	if len(services) > maxServices {
		return fmt.Errorf("больше %d групп в каталоге", maxServices)
	}
	raw, err := json.Marshal(catalogDoc{SchemaVersion: 1, Version: 1 << 62, Services: services})
	if err != nil {
		return err
	}
	if len(raw) > maxCatalogBytes {
		return fmt.Errorf("каталог превышает 1 МиБ")
	}
	seen := map[string]bool{}
	for _, s := range services {
		if seen[s.ID] {
			return fmt.Errorf("повторная группа %q", s.ID)
		}
		seen[s.ID] = true
		if err := validateService(s); err != nil {
			return err
		}
		for _, m := range s.DefaultModes {
			if m != SideBypass && m != SideProxy {
				return fmt.Errorf("неизвестный режим %q", m)
			}
		}
	}
	return nil
}

// catalogDoc is the document a client fetches.
type catalogDoc struct {
	SchemaVersion int       `json:"schemaVersion"`
	Version       int64     `json:"version"`
	Services      []Service `json:"services"`
}

func validateService(s Service) error {
	if !validID.MatchString(s.ID) || strings.TrimSpace(s.Name) == "" || len(s.Name) > 100 || (s.Icon != "" && !validID.MatchString(s.Icon)) {
		return fmt.Errorf("некорректный ID/название группы %q", s.ID)
	}
	if err := validateValues("domains", s.Domains); err != nil {
		return fmt.Errorf("%s: %w", s.ID, err)
	}
	if err := validateValues("ips", s.IPs); err != nil {
		return fmt.Errorf("%s: %w", s.ID, err)
	}
	for _, perOS := range []struct {
		category string
		lists    map[string][]string
	}{{"processes", s.Processes}, {"folders", s.Folders}} {
		for platform, entries := range perOS.lists {
			if !validPlatform(platform) {
				return fmt.Errorf("неизвестная платформа %q", platform)
			}
			if err := validateValues(perOS.category, entries); err != nil {
				return fmt.Errorf("%s: %w", s.ID, err)
			}
		}
	}
	n := len(s.Domains) + len(s.IPs)
	for _, p := range platforms {
		n += len(s.Processes[p]) + len(s.Folders[p])
	}
	if n == 0 {
		return fmt.Errorf("пустая группа %q", s.ID)
	}
	return nil
}

// validateValues mirrors routing.ValidateValues, except that a duplicate is
// an error here: the client drops it silently, the admin should see it.
func validateValues(category string, entries []string) error {
	if len(entries) > maxRulesPerCategory {
		return fmt.Errorf("слишком много правил")
	}
	seen := map[string]bool{}
	for _, value := range entries {
		if err := CanonicalRule(category, value); err != nil {
			return err
		}
		if seen[value] {
			return fmt.Errorf("правило %q повторяется", value)
		}
		seen[value] = true
	}
	return nil
}

// CanonicalRule accepts a rule only in the exact form the client stores.
func CanonicalRule(category, value string) error {
	if len(value) > 512 || strings.ContainsAny(value, "\x00\r\n") {
		return fmt.Errorf("некорректное правило")
	}
	normal, err := NormalizeRule(category, value)
	if err != nil {
		return err
	}
	if value != normal {
		return fmt.Errorf("правило %q должно быть записано как %q", value, normal)
	}
	return nil
}

// NormalizeRule is routing.NormalizeValue, so the editor can offer the
// canonical form of what was pasted.
func NormalizeRule(category, value string) (string, error) {
	value = strings.TrimSpace(value)
	if len(value) > 512 || strings.ContainsAny(value, "\x00\r\n") {
		return "", fmt.Errorf("некорректное правило")
	}
	if value == "" {
		return "", fmt.Errorf("пустое значение")
	}
	switch category {
	case "ips":
		return normalizeIP(value)
	case "domains":
		return normalizeDomain(value)
	case "processes":
		return normalizeProcess(value)
	case "folders":
		return normalizeFolder(value)
	default:
		return "", fmt.Errorf("неизвестная категория: %s", category)
	}
}

func normalizeIP(value string) (string, error) {
	if p, err := netip.ParsePrefix(value); err == nil {
		return p.Masked().String(), nil
	}
	if a, err := netip.ParseAddr(value); err == nil {
		return netip.PrefixFrom(a, a.BitLen()).String(), nil
	}
	if host := hostFromURLish(value); host != "" && !isIPish(host) {
		return "", fmt.Errorf("%q — это не ip: добавь %q в домены", value, host)
	}
	return "", fmt.Errorf("%q — не ip и не подсеть; примеры: 1.2.3.4, 192.168.0.0/16, 2001:db8::/32", value)
}

func normalizeProcess(value string) (string, error) {
	name := strings.TrimSpace(strings.Trim(value, `"'`))
	if i := strings.LastIndexAny(name, `\/`); i >= 0 {
		name = name[i+1:]
	}
	name = strings.TrimSpace(name)
	if name == "" {
		return "", fmt.Errorf("%q — не удалось извлечь имя приложения", value)
	}
	if strings.ContainsAny(name, `*?<>|"`) {
		return "", fmt.Errorf("%q — не похоже на имя приложения", value)
	}
	return name, nil
}

func normalizeFolder(value string) (string, error) {
	frag := strings.TrimSpace(strings.Trim(value, `"'`))
	frag = strings.ReplaceAll(frag, `\`, "/")
	if len(frag) >= 2 && frag[1] == ':' {
		frag = frag[2:]
	}
	for strings.Contains(frag, "//") {
		frag = strings.ReplaceAll(frag, "//", "/")
	}
	frag = strings.TrimPrefix(frag, "/")
	if strings.Trim(frag, "/") == "" {
		return "", fmt.Errorf("%q — пустой путь", value)
	}
	if !strings.Contains(frag, "/") {
		return "", fmt.Errorf("%q — нужен кусок пути со слешем, например %q", value, frag+"/")
	}
	if strings.ContainsAny(frag, `*?<>|"`) {
		return "", fmt.Errorf("%q — не похоже на путь", value)
	}
	return frag, nil
}

var allowedZoneSuffixes = map[string]string{
	"ru":           "ru",
	"su":           "su",
	"xn--p1ai":     "xn--p1ai",
	"рф":           "xn--p1ai",
	"xn--p1acf":    "xn--p1acf",
	"рус":          "xn--p1acf",
	"xn--80adxhks": "xn--80adxhks",
	"москва":       "xn--80adxhks",
	"xn--d1acj3b":  "xn--d1acj3b",
	"дети":         "xn--d1acj3b",
	"moscow":       "moscow",
	"tatar":        "tatar",
	"by":           "by",
	"xn--90ais":    "xn--90ais",
	"бел":          "xn--90ais",
	"kz":           "kz",
	"xn--80ao21a":  "xn--80ao21a",
	"қаз":          "xn--80ao21a",
}

func normalizeDomain(value string) (string, error) {
	host := value
	if h := hostFromURLish(value); h != "" {
		host = h
	}
	host = strings.TrimSuffix(strings.TrimPrefix(host, "*."), ".")
	host = strings.TrimPrefix(host, ".")
	host = strings.ToLower(strings.TrimSpace(host))
	if canonical, ok := allowedZoneSuffixes[host]; ok {
		host = canonical
	}
	if host == "" {
		return "", fmt.Errorf("%q — не удалось извлечь домен", value)
	}
	if isIPish(host) {
		return "", fmt.Errorf("%q — это ip: добавь его в ip", host)
	}
	if strings.ContainsAny(host, " \t/\\?#@") {
		return "", fmt.Errorf("%q — не похоже на домен", value)
	}
	if !strings.Contains(host, ".") && allowedZoneSuffixes[host] == "" {
		return "", fmt.Errorf("%q — домен без точки, нужен вид example.com", host)
	}
	if len(host) > 253 {
		return "", fmt.Errorf("слишком длинный домен")
	}
	for _, label := range strings.Split(host, ".") {
		if !domainLabel.MatchString(label) {
			return "", fmt.Errorf("некорректный домен %q", host)
		}
	}
	return host, nil
}

func hostFromURLish(value string) string {
	s := value
	if !strings.Contains(s, "://") && strings.ContainsAny(s, "/?#") {
		s = "//" + s
	} else if !strings.Contains(s, "://") {
		return stripPort(s)
	}
	u, err := url.Parse(s)
	if err != nil || u.Host == "" {
		return ""
	}
	return stripPort(u.Host)
}

func stripPort(s string) string {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "[") {
		if i := strings.Index(s, "]"); i > 0 {
			return s[1:i]
		}
		return s
	}
	if _, err := netip.ParseAddr(s); err == nil {
		return s
	}
	if i := strings.LastIndex(s, ":"); i > 0 {
		if _, err := netip.ParseAddr(s[:i]); err == nil || !strings.Contains(s[:i], ":") {
			return s[:i]
		}
	}
	return s
}

func isIPish(s string) bool {
	if _, err := netip.ParseAddr(s); err == nil {
		return true
	}
	_, err := netip.ParsePrefix(s)
	return err == nil
}
